 */import React, { useEffect, useState } from "react";
import Teachernav from "./teachernav";
import axios from "axios";
import { Link } from "react-router-dom";
import toast from "react-hot-toast";

const ViewStudents = () => {
  const [users, setUsers] = useState([]);
  const [classFilter, setClassFilter] = useState("");

  // Fetch students (optionally by class)
  const fetchStudents = async (cls) => {
    try {
      const url = cls
        ? `http://localhost:8009/api/users/class1/${cls}`
        : "http://localhost:8009/api/users";
      const response = await axios.get(url);
      setUsers(response.data);
    } catch (error) {
      console.log("❌ Error fetching users:", error);
      toast.error("Failed to fetch students");
    }
  };

  useEffect(() => {
    fetchStudents(classFilter);
  }, [classFilter]);

  // Delete student
  const deleteUser = async (userId) => {
    try {
      const response = await axios.delete(
        `http://localhost:8009/api/delete/user/${userId}`
      );
      setUsers((prev) => prev.filter((user) => user._id !== userId));
      toast.success(response.data.message || "User deleted successfully");
    } catch (error) {
      console.log("❌ Error deleting user:", error);
      toast.error("Failed to delete user");
    }
  };

  // Promote all students in the selected class
  const promoteAllClassesHandler = async () => {
    if (!classFilter) {
      toast.error("Please select a class first!");
      return;
    }

    const isConfirmed = window.confirm(
      `Are you sure you want to promote all students in Class ${classFilter}?`
    );
    if (!isConfirmed) return;

    try {
      const response = await axios.post(
        "http://localhost:8009/api/promote/class",
        { currentClass: classFilter } // Send the selected class
      );
      toast.success(response.data.message || "Promotion successful");
      fetchStudents(classFilter); // Refresh after promotion
    } catch (error) {
      console.log("❌ Error promoting classes:", error);
      const msg = error.response?.data?.message || "Failed to promote classes";
      toast.error(msg);
    }
  };

  return (
    <div className="StudentTable" style={{ color: "black", padding: "20px" }}>
      <Teachernav />

      {/* Class Filter */}
      <div style={{ marginBottom: "20px", display: "flex", gap: "15px" }}>
        <label>Filter by Class: </label>
        <select
          value={classFilter}
          onChange={(e) => setClassFilter(e.target.value)}
        >
          <option value="">-- All Classes --</option>
          {Array.from({ length: 10 }, (_, i) => (
            <option key={i + 1} value={i + 1}>
              {i + 1}
            </option>
          ))}
        </select>

        <button
          onClick={promoteAllClassesHandler}
          className="btn btn-warning"
          style={{ padding: "5px 15px" }}
        >
          Promote Class ⬆️
        </button>

        <Link to="/Add_delete" className="btn btn-primary">
          Add User
        </Link>
      </div>

      <table className="table table-bordered">
        <thead>
          <tr>
            <th>S.No.</th>
            <th>Name</th>
            <th>Class</th>
            <th>Roll</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.length > 0 ? (
            users.map((user, index) => (
              <tr key={user._id}>
                <td>{index + 1}</td>
                <td>{user.name}</td>
                <td>{user.class1}</td>
                <td>{user.roll}</td>
                <td>
                  <Link to={`/update/${user._id}`} className="btn btn-info me-2">
                    Edit
                  </Link>
                  <button
                    onClick={() => deleteUser(user._id)}
                    className="btn btn-danger"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ViewStudents;
